def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_and_pre = v.split('+', 1)[0]
        if '-' in main_and_pre:
            core, pre = main_and_pre.split('-', 1)
        else:
            core, pre = main_and_pre, None

        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        if pre is None:
            has_pre_flag = 1  # no prerelease sorts after
            ids_key = []
        else:
            has_pre_flag = 0  # has prerelease sorts before
            ids = pre.split('.')
            ids_key = []
            for ident in ids:
                if ident.isdigit():
                    ids_key.append((0, int(ident)))
                else:
                    ids_key.append((1, ident))

        return (major, minor, patch, has_pre_flag, ids_key)

    return sorted(versions, key=parse)

